--
-- V2__create_comment_index.sql
-- 对应 Go 版 service/comment/rpc/internal/model/data_model.go:22-40 的 CommentIndex
--
-- ⚠️ **id 不自增**：Go 侧是 `primaryKey;autoIncrement:false`，值来自雪花算法
--    （create_comment_logic.go:93 snowflake.GetID()），由 Kafka 消息携带落库。
--    ⇒ 这里必须 `GENERATED BY DEFAULT AS IDENTITY` 之外**去掉**自增，
--    用 BIGINT PRIMARY KEY 而不带 IDENTITY / BIGSERIAL，否则 PG 会分配一个与雪花 ID 无关的序列值。

CREATE TABLE IF NOT EXISTS comment_index (
    id            BIGINT      PRIMARY KEY,          -- Go: Id int64 `primaryKey;autoIncrement:false`（雪花 ID）
    target_type   VARCHAR(32) NOT NULL,             -- Go: TargetType   string `type:varchar(32);not null`
    target_id     VARCHAR(64) NOT NULL,             -- Go: TargetId     string `type:varchar(64);not null`
    user_id       BIGINT      NOT NULL,             -- Go: UserId       int64  `not null` 发布者Uid
    root_id       BIGINT      NOT NULL DEFAULT 0,   -- Go: RootId       int64  `not null;default:0` 根评论ID（0=根评论本身）
    parent_id     BIGINT      NOT NULL DEFAULT 0,   -- Go: ParentId     int64  `not null;default:0` 父评论Id
    like_count    BIGINT      NOT NULL DEFAULT 0,   -- Go: LikeCount    int64  `not null;default:0`
    dislike_count BIGINT      NOT NULL DEFAULT 0,   -- Go: DislikeCount int64  `not null;default:0`
    reply_count   BIGINT      NOT NULL DEFAULT 0,   -- Go: ReplyCount   int64  `not null;default:0` 子评论数
    state         INTEGER     NOT NULL DEFAULT 0,   -- Go: State int32 `not null;default:0` 0正常 1审核 2删除 3封禁
    attribute     BIGINT      NOT NULL DEFAULT 0,   -- Go: Attribute int64 `not null;default:0` 属性位图
    created_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,   -- Go: CreatedAt time.Time `autoCreateTime`
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP    -- Go: UpdatedAt time.Time `autoUpdateTime`
);

-- Go: `index:idx_target_root_time,priority:1..4` 打在 TargetType / TargetId / RootId / CreatedAt 四列上
-- ⇒ 这是一个 (target_type, target_id, root_id, created_at) 的复合索引。
--
-- 它同时承载 GetComment 的两条热路径（comment.go:383-399）：
--   WHERE target_type = ? AND target_id = ? AND root_id = ?  [+ state = 0]
--   ORDER BY created_at DESC, id DESC       ← 时间序
--   ORDER BY like_count  DESC, id DESC     ← 热度序（like_count 不在索引里，该分支仍要排序）
CREATE INDEX IF NOT EXISTS idx_target_root_time
    ON comment_index (target_type, target_id, root_id, created_at);